"""Write the API contract generated by FastAPI to contracts/.

Run after changing routes or schemas:  python scripts/export_openapi.py
"""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from dialin_api.main import create_app  # noqa: E402

CONTRACT = ROOT / "contracts" / "dialin-api.openapi.json"

if __name__ == "__main__":
    app = create_app("sqlite:///:memory:", demo_data=False)
    CONTRACT.write_text(json.dumps(app.openapi(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Wrote {CONTRACT.relative_to(ROOT)}")
